package com.example.domain.model.i18n

internal object DuaHi2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("तीन क़ुल (मुअव्विज़ात)", "(सूरह इख़लास) कहो: वह अल्लाह एक है। अल्लाह बेनियाज़ है। न उसने किसी को जना, न वह किसी से जना गया। और कोई उसका हमसर नहीं।\n\n(सूरह फ़लक़) कहो: मैं सुबह के रब की पनाह माँगता हूँ, हर उस चीज़ के शर से जो उसने पैदा की, और अँधेरी रात के शर से जब वह छा जाए, और गिरहों में फूँकने वालियों के शर से, और हसद करने वाले के शर से जब वह हसद करे।\n\n(सूरह नास) कहो: मैं इंसानों के रब की पनाह माँगता हूँ, इंसानों के बादशाह की, इंसानों के माबूद की, उस वसवसा डालने वाले के शर से जो (अल्लाह का ज़िक्र सुनकर) पीछे हट जाता है, जो लोगों के दिलों में वसवसा डालता है, चाहे वह जिन्नों में से हो या इंसानों में से।", "सुबह-शाम तीनों सूरतें तीन-तीन बार, और सोने से पहले हाथों पर दम करके जिस्म पर फेरना।", "सुबह-शाम तीन बार पढ़ना हर चीज़ से काफ़ी हो जाता है।"),
        "dua_sabr" to DuaText("सब्र और साबित-क़दमी के लिए", "ऐ हमारे रब! हम पर सब्र उंडेल दे, हमारे क़दम जमा दे और काफ़िर क़ौम के मुक़ाबले में हमारी मदद फ़रमा।", "मुश्किल और मुक़ाबले के वक़्त।", "तालूत के लश्कर की दुआ।"),
        "dua_rabbana_innana_amanna" to DuaText("मग़फ़िरत और आग से हिफ़ाज़त", "ऐ हमारे रब! हम ईमान लाए, तो हमारे गुनाह माफ़ फ़रमा और हमें आग के अज़ाब से बचा।", "क़ुरआनी दुआ।", "मुत्तक़ीन की सिफ़त में बयान की गई दुआ।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("हमारे काम में रहनुमाई (असहाब-ए-कहफ़)", "ऐ हमारे रब! हमें अपने पास से रहमत अता फ़रमा और हमारे काम में हमारे लिए दुरुस्ती का सामान कर दे।", "असहाब-ए-कहफ़ की दुआ।", "फ़ैसलों और मुश्किल हालात में रहनुमाई।"),
        "dua_musa_faqir" to DuaText("रिज़्क़ के लिए हज़रत मूसा (अ.) की दुआ", "ऐ मेरे रब! जो भी भलाई तू मुझ पर उतारे, मैं उसका मोहताज हूँ।", "रिज़्क़ और भलाई की तलब — मदयन में हज़रत मूसा (अ.) की दुआ।", "इस दुआ के बाद अल्लाह ने मूसा (अ.) को घर, रोज़गार और बीवी अता की।"),
        "dua_ayyub" to DuaText("बीमारी में हज़रत अय्यूब (अ.) की दुआ", "(ऐ मेरे रब!) मुझे तकलीफ़ पहुँची है और तू सब रहम करने वालों से ज़्यादा रहम करने वाला है।", "बीमारी और तकलीफ़ में।", "अल्लाह ने हज़रत अय्यूब (अ.) की तकलीफ़ दूर फ़रमा दी।"),
        "dua_husn_khatimah" to DuaText("मुसलमान होकर मौत (यूसुफ़ अ.)", "ऐ आसमानों और ज़मीन के पैदा करने वाले! तू ही दुनिया और आख़िरत में मेरा कारसाज़ है। मुझे इस्लाम की हालत में मौत दे और नेक लोगों के साथ मिला दे।", "अच्छे ख़ातमे की दुआ।", "हज़रत यूसुफ़ (अ.) की दुआ।"),
        "dua_shaitan_hamazat" to DuaText("शैतानों के वसवसों से पनाह", "ऐ मेरे रब! मैं शैतानों के वसवसों से तेरी पनाह माँगता हूँ, और ऐ मेरे रब! इससे भी तेरी पनाह कि वे मेरे पास आएँ।", "शैतानी वसवसों से पनाह।", "क़ुरआनी पनाह की दुआ।"),
        "dua_bad_character" to DuaText("बुरे अख़लाक़ से पनाह", "ऐ अल्लाह! मैं बुरे अख़लाक़, बुरे आमाल और बुरी ख़्वाहिशात से तेरी पनाह माँगता हूँ।", "बुरे अख़लाक़, आमाल और ख़्वाहिशात से पनाह।", "नबी ﷺ की पनाह की दुआ।"),
        "dua_zawal_nimah" to DuaText("नेमत छिन जाने से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ तेरी नेमत के ज़वाल से, तेरी दी हुई आफ़ियत के बदल जाने से, तेरे अचानक अज़ाब से और तेरी हर नाराज़गी से।", "नेमत छिन जाने और अचानक मुसीबत से पनाह।", "नबी ﷺ की दुआ।"),
        "dua_useless_knowledge" to DuaText("बेफ़ायदा इल्म से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ ऐसे इल्म से जो फ़ायदा न दे, ऐसे दिल से जो न डरे, ऐसे नफ़्स से जो सेर न हो, और ऐसी दुआ से जो क़बूल न हो।", "बेफ़ायदा इल्म और बेख़ौफ़ दिल से पनाह।", "नबी ﷺ की पनाह की दुआ।"),
        "dua_beneficial_knowledge" to DuaText("नफ़ा देने वाला इल्म और हलाल रिज़्क़", "ऐ अल्लाह! मैं तुझसे नफ़ा देने वाला इल्म, पाकीज़ा रिज़्क़ और क़बूल होने वाला अमल माँगता हूँ।", "फ़ज्र की नमाज़ के बाद।", "नबी ﷺ फ़ज्र के सलाम के बाद यह दुआ फ़रमाते।"),
        "dua_leprosy_diseases" to DuaText("बुरी बीमारियों से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ सफ़ेद दाग़ (बर्स), दीवानगी, कोढ़ और तमाम बुरी बीमारियों से।", "बुरी बीमारियों से हिफ़ाज़त।", "सेहत की हिफ़ाज़त की मसनून दुआ।"),
        "dua_fear_people" to DuaText("दुश्मन या ज़ालिम का ख़ौफ़", "ऐ अल्लाह! हम तुझे उनके मुक़ाबले में करते हैं और उनके शर से तेरी पनाह माँगते हैं।", "किसी क़ौम या शख़्स के शर का ख़ौफ़ हो।", "नबी ﷺ किसी क़ौम से ख़तरा महसूस करते तो यह फ़रमाते।"),
        "dua_shirk_protection" to DuaText("छुपे शिर्क से हिफ़ाज़त", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ इससे कि जानते-बूझते तेरे साथ शिर्क करूँ, और जो अनजाने में हो उसकी माफ़ी माँगता हूँ।", "दिखावे और छुपे शिर्क से बचने के लिए।", "शिर्क-ए-ख़फ़ी (छुपा शिर्क) चींटी की चाल से भी ज़्यादा छुपा है।"),
        "dua_rain" to DuaText("बारिश होते वक़्त", "ऐ अल्लाह! नफ़ा देने वाली बारिश बरसा।", "बारिश होते वक़्त।", "बारिश दुआ की क़बूलियत का वक़्त है।"),
        "dua_after_rain" to DuaText("बारिश के बाद", "हम पर अल्लाह के फ़ज़्ल और उसकी रहमत से बारिश हुई।", "बारिश के बाद।", "यह कहने वाला अल्लाह पर ईमान रखने वाला है।"),
        "dua_istisqa" to DuaText("बारिश माँगना (इस्तिस्क़ा)", "ऐ अल्लाह! हम पर बारिश बरसा (तीन बार)।", "बारिश न होने पर।", "नबी ﷺ ने जुमे के ख़ुत्बे में यह दुआ की और बारिश हुई।"),
        "dua_heavy_rain" to DuaText("ज़्यादा बारिश", "ऐ अल्लाह! हमारे आस-पास (बरसा), हम पर नहीं।", "बारिश ज़्यादा हो जाए तो।", "नबी ﷺ की दुआ से बादल हट गए।"),
        "dua_wind" to DuaText("तेज़ हवा चलने पर", "ऐ अल्लाह! मैं तुझसे इसकी भलाई, जो इसमें है उसकी भलाई और जिसके साथ यह भेजी गई उसकी भलाई माँगता हूँ, और इसके शर, जो इसमें है उसके शर और जिसके साथ यह भेजी गई उसके शर से तेरी पनाह माँगता हूँ।", "तेज़ हवा/आँधी चलने पर।", "नबी ﷺ आँधी के वक़्त यह दुआ फ़रमाते।"),
        "dua_thunder" to DuaText("बादल की गरज सुनकर", "पाक है वह ज़ात जिसकी तस्बीह गरज उसकी तारीफ़ के साथ करती है और फ़रिश्ते उसके ख़ौफ़ से।", "बादल की गरज सुनकर — हज़रत अब्दुल्लाह बिन ज़ुबैर (रज़ि.) का अमल।", "सूरह रअद (13:13) से माख़ूज़।"),
        "dua_new_moon" to DuaText("नया चाँद देखकर", "ऐ अल्लाह! इस चाँद को हम पर बरकत, ईमान, सलामती और इस्लाम के साथ तुलू फ़रमा। (ऐ चाँद!) मेरा और तेरा रब अल्लाह है।", "नया चाँद देखकर।", "हर नए महीने की मसनून दुआ।"),
        "dua_janaza_adult" to DuaText("नमाज़-ए-जनाज़ा (बालिग़)", "ऐ अल्लाह! हमारे ज़िंदों और मुर्दों, हाज़िर और ग़ायब, छोटों और बड़ों, मर्दों और औरतों सबको बख़्श दे। ऐ अल्लाह! हममें से जिसे ज़िंदा रखे उसे इस्लाम पर ज़िंदा रख, और जिसे मौत दे उसे ईमान पर मौत दे।", "नमाज़-ए-जनाज़ा की तीसरी तकबीर के बाद।", "बालिग़ मय्यत की मसनून दुआ।"),
        "dua_janaza_child" to DuaText("नमाज़-ए-जनाज़ा (बच्चा)", "ऐ अल्लाह! इसे हमारे लिए आगे जाने वाला (मेज़बान) बना, इसे हमारे लिए अज्र और ज़ख़ीरा बना, और इसे हमारे लिए सिफ़ारिश करने वाला और जिसकी सिफ़ारिश क़बूल हो, बना।", "नाबालिग़ बच्चे की नमाज़-ए-जनाज़ा में (लड़की हो तो 'इज्अल्हा')।", "अहनाफ़ के यहाँ मामूल मसनून दुआ।"),
        "dua_mayyit_awf" to DuaText("मय्यत के लिए तफ़सीली दुआ", "ऐ अल्लाह! इसे बख़्श दे, इस पर रहम फ़रमा, इसे आफ़ियत दे, इसे माफ़ फ़रमा, इसकी मेहमानी इज़्ज़त वाली कर, इसकी क़ब्र कुशादा कर, इसे पानी, बर्फ़ और ओलों से धो दे, और इसे गुनाहों से ऐसे साफ़ कर दे जैसे सफ़ेद कपड़ा मैल से साफ़ किया जाता है।", "जनाज़े में या मय्यत के लिए।", "हज़रत औफ़ बिन मालिक (रज़ि.) ने तमन्ना की कि काश यह मय्यत मैं होता।"),
        "dua_visiting_graves" to DuaText("क़ब्रिस्तान की ज़ियारत", "ऐ मोमिन और मुस्लिम घर वालो, तुम पर सलाम हो। हम भी इन शा अल्लाह तुमसे मिलने वाले हैं। मैं अल्लाह से अपने और तुम्हारे लिए आफ़ियत माँगता हूँ।", "क़ब्रिस्तान में दाख़िल होते वक़्त।", "क़ब्रों की ज़ियारत मौत और आख़िरत याद दिलाती है।"),
        "dua_closing_eyes" to DuaText("मय्यत की आँखें बंद करते वक़्त", "ऐ अल्लाह! (फ़ुलाँ) को बख़्श दे, हिदायत पाए लोगों में इसका दर्जा बुलंद कर, इसके पीछे रहने वालों में इसका जानशीन बन जा, ऐ रब्बुल आलमीन! हमें और इसे बख़्श दे, इसकी क़ब्र कुशादा कर और उसमें रोशनी कर दे।", "मय्यत की आँखें बंद करते वक़्त (नाम लेकर)।", "नबी ﷺ ने हज़रत अबू सलमा (रज़ि.) के लिए यह दुआ फ़रमाई।"),
        "dua_condolence" to DuaText("ताज़ियत", "बेशक अल्लाह ही का था जो उसने ले लिया और उसी का है जो उसने दिया, और उसके यहाँ हर चीज़ का एक मुक़र्रर वक़्त है, तो सब्र करो और सवाब की उम्मीद रखो।", "किसी के इंतिक़ाल पर घर वालों से ताज़ियत।", "नबी ﷺ ने अपनी साहबज़ादी को यह पैग़ाम भेजा।"),
        "dua_placing_in_grave" to DuaText("मय्यत को क़ब्र में उतारना", "अल्लाह के नाम से और रसूलुल्लाह ﷺ की मिल्लत पर।", "मय्यत को क़ब्र में उतारते वक़्त।", "तदफ़ीन की मसनून दुआ।"),
        "dua_sneezing" to DuaText("छींक आने पर", "सारी तारीफ़ अल्लाह के लिए। — अल्लाह तुम पर रहम करे। — अल्लाह तुम्हें हिदायत दे और तुम्हारा हाल दुरुस्त करे।", "छींक आने पर; सुनने वाला 'यरहमुकल्लाह' कहे, फिर छींकने वाला जवाब दे।", "मुसलमान के मुसलमान पर हक़ों में से है।"),
        "dua_toilet_enter" to DuaText("बैतुल-ख़ला में दाख़िल होना", "अल्लाह के नाम से। ऐ अल्लाह! मैं नापाक जिन्नों (नर और मादा) से तेरी पनाह माँगता हूँ।", "बैतुल-ख़ला में बायाँ पाँव रखने से पहले।", "बिस्मिल्लाह जिन्नात और इंसान के पर्दे के बीच आड़ बन जाती है।"),
        "dua_toilet_exit" to DuaText("बैतुल-ख़ला से निकलना", "(ऐ अल्लाह!) मैं तेरी मग़फ़िरत चाहता हूँ।", "बैतुल-ख़ला से दायाँ पाँव बाहर निकालते वक़्त।", "नबी ﷺ बैतुल-ख़ला से निकलकर यह फ़रमाते।"),
        "dua_thanking" to DuaText("किसी का शुक्रिया", "अल्लाह तुम्हें बेहतरीन बदला दे।", "कोई एहसान करे तो।", "जिसने यह कहा उसने तारीफ़ का हक़ अदा कर दिया।"),
        "dua_love_for_allah" to DuaText("जब कोई कहे 'मैं तुमसे अल्लाह के लिए मुहब्बत करता हूँ'", "वह (अल्लाह) तुमसे मुहब्बत करे जिसके लिए तुमने मुझसे मुहब्बत की।", "कोई कहे 'मैं तुमसे अल्लाह के लिए मुहब्बत करता हूँ'।", "अल्लाह के लिए मुहब्बत की मसनून जवाबी दुआ।"),
        "dua_seeing_muslim_smile" to DuaText("सलाम", "तुम पर सलामती, अल्लाह की रहमत और उसकी बरकतें हों।", "मुसलमान से मिलते वक़्त।", "पूरा सलाम कहने पर तीस नेकियाँ मिलती हैं।"),
        "dua_dressing" to DuaText("कपड़े पहनना", "सारी तारीफ़ अल्लाह के लिए जिसने मुझे यह कपड़ा पहनाया और मेरी किसी ताक़त और क़ुव्वत के बिना अता किया।", "कपड़े पहनते वक़्त।", "पिछले गुनाहों की माफ़ी की ख़ुशख़बरी।"),
        "dua_rooster_donkey" to DuaText("मुर्ग़ या गधे की आवाज़ सुनकर", "ऐ अल्लाह! मैं तेरा फ़ज़्ल माँगता हूँ (मुर्ग़)। — मैं अल्लाह की पनाह माँगता हूँ मरदूद शैतान से (गधा)।", "मुर्ग़ की आवाज़ पर अल्लाह का फ़ज़्ल माँगें, गधे के रेंकने पर शैतान से पनाह।", "मुर्ग़ फ़रिश्ता देखता है और गधा शैतान।"),
        "dua_something_liked" to DuaText("कोई पसंदीदा चीज़ देखकर (नज़र से बचाव)", "जो अल्लाह ने चाहा। ऐ अल्लाह! इसमें बरकत दे।", "किसी की अच्छी चीज़ देखकर बरकत की दुआ दें।", "बरकत की दुआ देने से नज़र नहीं लगती।"),
        "dua_sell_buy_debt_repaid" to DuaText("क़र्ज़ लौटाते वक़्त", "अल्लाह तुम्हारे घर वालों और माल में बरकत दे।", "क़र्ज़ लौटाते वक़्त क़र्ज़ देने वाले के लिए।", "क़र्ज़ का बदला शुक्र और अदायगी है।"),
        "dua_talbiyah" to DuaText("तलबिया", "मैं हाज़िर हूँ, ऐ अल्लाह मैं हाज़िर हूँ। मैं हाज़िर हूँ, तेरा कोई शरीक नहीं, मैं हाज़िर हूँ। बेशक सारी तारीफ़, नेमत और बादशाहत तेरी ही है, तेरा कोई शरीक नहीं।", "एहराम बाँधने के बाद बुलंद आवाज़ से।", "हज और उमरा का शिआर।"),
        "dua_yamani_hajar" to DuaText("रुक्न-ए-यमानी और हजर-ए-असवद के बीच", "ऐ हमारे रब! हमें दुनिया में भी भलाई दे और आख़िरत में भी भलाई दे, और हमें आग के अज़ाब से बचा।", "तवाफ़ में रुक्न-ए-यमानी और हजर-ए-असवद के दरमियान।", "नबी ﷺ तवाफ़ में इस जगह यह पढ़ते थे।"),
        "dua_safa_marwa" to DuaText("सफ़ा और मरवा पर", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाहत और तारीफ़ है और वह हर चीज़ पर क़ादिर है। अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसने अपना वादा पूरा किया, अपने बंदे की मदद की और अकेले सारे लश्करों को शिकस्त दी।", "सफ़ा पर चढ़कर क़िब्ला-रुख़ होकर (तीन बार)।", "नबी ﷺ का सफ़ा और मरवा पर ज़िक्र।"),
        "dua_arafah" to DuaText("अरफ़ा के दिन की बेहतरीन दुआ", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाहत और तारीफ़ है और वह हर चीज़ पर क़ादिर है।", "यौम-ए-अरफ़ा — सबसे बेहतर दुआ।", "सबसे बेहतर दुआ अरफ़ा के दिन की दुआ है, और सबसे बेहतर कलिमा यह है।"),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तशरीक़", "अल्लाह सबसे बड़ा है, अल्लाह सबसे बड़ा है। अल्लाह के सिवा कोई माबूद नहीं। अल्लाह सबसे बड़ा है, अल्लाह सबसे बड़ा है, और सारी तारीफ़ अल्लाह ही के लिए है।", "9 ज़िलहिज्जा फ़ज्र से 13 ज़िलहिज्जा अस्र तक हर फ़र्ज़ नमाज़ के बाद।", "हज़रत अली और इब्न मसऊद (रज़ि.) से मनक़ूल — अहनाफ़ के यहाँ वाजिब।"),
        "dua_zamzam" to DuaText("ज़मज़म पीते वक़्त", "ऐ अल्लाह! मैं तुझसे नफ़ा देने वाला इल्म, कुशादा रिज़्क़ और हर बीमारी से शिफ़ा माँगता हूँ।", "ज़मज़म पीते वक़्त जो नीयत हो उसकी दुआ करें।", "ज़मज़म जिस नीयत से पिया जाए उसी के लिए है (इब्न माजा 3062)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("तख़लीक़ पर ग़ौर", "ऐ हमारे रब! तूने यह सब बेकार पैदा नहीं किया, तू पाक है, तो हमें आग के अज़ाब से बचा।", "आसमान और ज़मीन की तख़लीक़ पर ग़ौर करने वालों की दुआ।", "अहल-ए-अक़्ल (उलुल-अल्बाब) की दुआ।"),
        "dua_q_sami_na_munadiyan" to DuaText("हमने ईमान के पुकारने वाले को सुना", "ऐ हमारे रब! हमने एक पुकारने वाले को ईमान की तरफ़ पुकारते सुना कि अपने रब पर ईमान लाओ, तो हम ईमान ले आए। ऐ हमारे रब! हमारे गुनाह बख़्श दे, हमारी बुराइयाँ हमसे दूर कर दे और हमें नेक लोगों के साथ मौत दे।", "ईमान और नेक लोगों के साथ मौत की दुआ।", "मग़फ़िरत और हुस्न-ए-ख़ातिमा की दुआ।"),
        "dua_q_atina_ma_waadtana" to DuaText("जो तूने वादा किया वह अता कर", "ऐ हमारे रब! हमें वह अता फ़रमा जिसका तूने अपने रसूलों के ज़रिए वादा किया, और क़यामत के दिन हमें रुसवा न कर, बेशक तू वादा-ख़िलाफ़ी नहीं करता।", "क़यामत की रुसवाई से पनाह।", "आख़िरत की इज़्ज़त की तलब।"),
        "dua_q_israfana" to DuaText("हमारी ज़्यादतियाँ माफ़ कर", "ऐ हमारे रब! हमारे गुनाह और हमारे कामों में हमारी ज़्यादती माफ़ फ़रमा, हमारे क़दम जमा दे और काफ़िर क़ौम पर हमारी मदद फ़रमा।", "पिछले नबियों के साथियों की दुआ।", "साबित-क़दमी और माफ़ी की दुआ।"),
        "dua_q_jamiun_nas" to DuaText("तू लोगों को जमा करने वाला है", "ऐ हमारे रब! बेशक तू लोगों को उस दिन जमा करने वाला है जिसमें कोई शक नहीं। बेशक अल्लाह वादा-ख़िलाफ़ी नहीं करता।", "क़यामत पर यक़ीन का इक़रार।", "इल्म में पुख़्ता लोगों की दुआ।"),
        "dua_q_maash_shahidin" to DuaText("हमें गवाहों में लिख ले", "ऐ हमारे रब! हम ईमान लाए, तो हमें गवाही देने वालों के साथ लिख ले।", "हक़ पहचानकर ईमान लाने वालों की दुआ।", "ईमान की क़बूलियत की दुआ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("ज़ालिमों के साथ न कर", "ऐ हमारे रब! हमें ज़ालिम लोगों के साथ न कर।", "अहल-ए-आराफ़ की दुआ।", "ज़ालिमों के अंजाम से पनाह।"),
        "dua_q_tawaffana_muslimin" to DuaText("सब्र और मुसलमान होकर मौत", "ऐ हमारे रब! हम पर सब्र उंडेल दे और हमें मुसलमान होने की हालत में मौत दे।", "फ़िरऔन के जादूगरों की दुआ जब वे ईमान लाए।", "आज़माइश में सब्र और ईमान पर ख़ातमा।"),
        "dua_q_la_tajalna_fitnah" to DuaText("ज़ालिमों के लिए आज़माइश न बना", "हमने अल्लाह पर भरोसा किया। ऐ हमारे रब! हमें ज़ालिम क़ौम के लिए आज़माइश न बना, और अपनी रहमत से हमें काफ़िर क़ौम से नजात दे।", "हज़रत मूसा (अ.) की क़ौम की दुआ।", "ज़ुल्म और ज़ालिमों से नजात की दुआ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("माफ़ी के लिए हज़रत नूह (अ.) की दुआ", "ऐ मेरे रब! मैं तेरी पनाह माँगता हूँ इससे कि तुझसे वह माँगूँ जिसका मुझे इल्म नहीं। अगर तू मुझे माफ़ न करे और मुझ पर रहम न करे तो मैं नुक़सान उठाने वालों में से हो जाऊँगा।", "हज़रत नूह (अ.) की तौबा की दुआ।", "अदब के साथ दुआ माँगने की तालीम।"),
        "dua_q_mudkhala_sidq" to DuaText("सच्चाई के साथ दाख़िल होना और निकलना", "ऐ मेरे रब! मुझे सच्चाई के साथ दाख़िल कर और सच्चाई के साथ निकाल, और अपने पास से मुझे मददगार ग़लबा अता फ़रमा।", "किसी नए काम, घर या जगह में दाख़िल होने से पहले।", "हिजरत के मौक़े पर नबी ﷺ को सिखाई गई दुआ।"),
        "dua_q_la_tadharni_fardan" to DuaText("मुझे अकेला न छोड़ (ज़करिया अ.)", "ऐ मेरे रब! मुझे अकेला न छोड़, और तू सबसे बेहतर वारिस है।", "औलाद की तलब के लिए।", "अल्लाह ने इस दुआ पर हज़रत यह्या (अ.) अता फ़रमाए।"),
        "dua_q_munzalan_mubarakan" to DuaText("बरकत वाली जगह उतार", "ऐ मेरे रब! मुझे बरकत वाली जगह उतार, और तू सबसे बेहतर उतारने वाला है।", "नए घर में शिफ़्ट होने या कहीं उतरने पर — हज़रत नूह (अ.) की दुआ।", "नए मक़ाम में बरकत की दुआ।"),
        "dua_q_amanna_faghfir" to DuaText("हम ईमान लाए, हमें बख़्श दे", "ऐ हमारे रब! हम ईमान लाए, तो हमें बख़्श दे और हम पर रहम फ़रमा, और तू सबसे बेहतर रहम करने वाला है।", "अल्लाह के नेक बंदों की दुआ।", "मग़फ़िरत और रहमत की जामे दुआ।"),
        "dua_q_isrif_jahannam" to DuaText("जहन्नम का अज़ाब फेर दे", "ऐ हमारे रब! जहन्नम का अज़ाब हमसे फेर दे, बेशक उसका अज़ाब चिमट जाने वाला है। बेशक वह बुरा ठिकाना और बुरी जगह है।", "इबादुर्रहमान (रहमान के बंदों) की दुआ।", "जहन्नम से पनाह की क़ुरआनी दुआ।"),
        "dua_q_hab_li_hukman" to DuaText("हिकमत और जन्नत (इब्राहीम अ.)", "ऐ मेरे रब! मुझे हिकमत अता फ़रमा और नेक लोगों के साथ मिला दे, बाद वालों में मेरा ज़िक्र-ए-ख़ैर जारी रख, और मुझे नेमतों वाली जन्नत के वारिसों में से बना।", "हिकमत, नेक लोगों की सोहबत और जन्नत की तलब।", "हज़रत इब्राहीम (अ.) की जामे दुआ।"),
        "dua_q_lut_najjini_ahli" to DuaText("मेरे घर वालों को बचा (लूत अ.)", "ऐ मेरे रब! मुझे और मेरे घर वालों को उनके कामों (के वबाल) से नजात दे।", "बुराई के माहौल से घर वालों की हिफ़ाज़त।", "बुराई से घर वालों की हिफ़ाज़त।"),
        "dua_q_sulaiman_awzini" to DuaText("शुक्र के लिए हज़रत सुलैमान (अ.) की दुआ", "ऐ मेरे रब! मुझे तौफ़ीक़ दे कि मैं तेरी उस नेमत का शुक्र करूँ जो तूने मुझ पर और मेरे वालिदैन पर की, और ऐसा नेक अमल करूँ जो तुझे पसंद हो, और अपनी रहमत से मुझे अपने नेक बंदों में दाख़िल फ़रमा।", "नेमत पर शुक्र की तौफ़ीक़।", "हज़रत सुलैमान (अ.) की शुक्र की दुआ।"),
        "dua_q_musa_zalamtu" to DuaText("मैंने अपनी जान पर ज़ुल्म किया (मूसा अ.)", "ऐ मेरे रब! मैंने अपनी जान पर ज़ुल्म किया, तो मुझे बख़्श दे।", "ग़लती हो जाने पर फ़ौरन तौबा।", "अल्लाह ने हज़रत मूसा (अ.) को माफ़ फ़रमा दिया।"),
        "dua_q_musa_najjini" to DuaText("ज़ालिमों से बचा (मूसा अ.)", "ऐ मेरे रब! मुझे ज़ालिम क़ौम से नजात दे।", "ज़ालिमों के ख़ौफ़ में।", "मिस्र से निकलते वक़्त हज़रत मूसा (अ.) की दुआ।"),
        "dua_q_lut_unsurni" to DuaText("फ़साद करने वालों के ख़िलाफ़ मदद (लूत अ.)", "ऐ मेरे रब! फ़साद करने वाली क़ौम के मुक़ाबले में मेरी मदद फ़रमा।", "फ़साद करने वालों के मुक़ाबले में मदद।", "हक़ पर साबित रहने वालों की दुआ।"),
        "dua_q_hab_li_salihin" to DuaText("नेक औलाद के लिए हज़रत इब्राहीम (अ.) की दुआ", "ऐ मेरे रब! मुझे नेक (औलाद) अता फ़रमा।", "नेक औलाद की तलब।", "इस दुआ पर हज़रत इस्माईल (अ.) अता हुए।"),
        "dua_q_wasita_kulla_shay" to DuaText("अर्श उठाने वाले फ़रिश्तों की दुआ", "ऐ हमारे रब! तेरी रहमत और इल्म हर चीज़ को घेरे हुए है, तो उन लोगों को बख़्श दे जिन्होंने तौबा की और तेरे रास्ते पर चले, और उन्हें जहन्नम के अज़ाब से बचा।", "अर्श उठाने वाले फ़रिश्ते मोमिनों के लिए यह दुआ करते हैं।", "फ़रिश्तों की दुआ में शामिल होने की नीयत से।"),
        "dua_q_ikhwanina" to DuaText("हमसे पहले गुज़रे भाइयों के लिए", "ऐ हमारे रब! हमें और हमारे उन भाइयों को बख़्श दे जो हमसे पहले ईमान लाए, और हमारे दिलों में ईमान वालों के लिए कोई कीना न रख। ऐ हमारे रब! बेशक तू बड़ा शफ़क़त वाला, रहम वाला है।", "पिछले मोमिनों के लिए और दिल की सफ़ाई की दुआ।", "सहाबा-ए-किराम (रज़ि.) और पिछले मोमिनों के लिए दुआ।"),
        "dua_q_alayka_tawakkalna" to DuaText("तुझ पर हमने भरोसा किया (इब्राहीम अ.)", "ऐ हमारे रब! हमने तुझ पर भरोसा किया, तेरी तरफ़ रुजू किया और तेरी ही तरफ़ लौटना है। ऐ हमारे रब! हमें काफ़िरों के लिए आज़माइश न बना और हमें बख़्श दे। ऐ हमारे रब! बेशक तू ग़ालिब, हिकमत वाला है।", "हज़रत इब्राहीम (अ.) और उनके साथियों की दुआ।", "तवक्कुल और रुजू की दुआ।"),
        "dua_q_atmim_nurana" to DuaText("हमारा नूर पूरा कर", "ऐ हमारे रब! हमारे लिए हमारा नूर पूरा कर दे और हमें बख़्श दे, बेशक तू हर चीज़ पर क़ादिर है।", "क़यामत के दिन मोमिनों की दुआ।", "पुल-सिरात पर नूर की तलब।"),
        "dua_q_asiya_baytan" to DuaText("जन्नत में घर (हज़रत आसिया)", "ऐ मेरे रब! मेरे लिए अपने पास जन्नत में घर बना दे, और मुझे फ़िरऔन और उसके अमल से नजात दे, और ज़ालिम क़ौम से नजात दे।", "फ़िरऔन की बीवी हज़रत आसिया की दुआ।", "अल्लाह ने उन्हें मोमिनों के लिए मिसाल बनाया।"),
        "dua_adhan_response" to DuaText("अज़ान का जवाब", "अल्लाह के बिना न कोई ताक़त है और न कोई क़ुव्वत।", "मुअज़्ज़िन जो कहे वही दोहराएँ; 'हय्या अलस्सलाह' और 'हय्या अलल-फ़लाह' पर यह कहें।", "दिल से जवाब देने वाला जन्नत में दाख़िल होगा।"),
        "dua_adhan_shahadah" to DuaText("मुअज़्ज़िन की शहादत के बाद", "और मैं भी गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, और मुहम्मद ﷺ उसके बंदे और रसूल हैं। मैं अल्लाह के रब, मुहम्मद ﷺ के रसूल और इस्लाम के दीन होने पर राज़ी हूँ।", "मुअज़्ज़िन की शहादतैन सुनकर।", "उसके गुनाह माफ़ कर दिए जाते हैं।"),
        "dua_istiftah_baid" to DuaText("शुरुआती दुआ: मुझे गुनाहों से दूर कर", "ऐ अल्लाह! मेरे और मेरे गुनाहों के बीच इतनी दूरी कर दे जितनी तूने मशरिक़ और मग़रिब में की। ऐ अल्लाह! मुझे गुनाहों से ऐसे साफ़ कर दे जैसे सफ़ेद कपड़ा मैल से साफ़ किया जाता है। ऐ अल्लाह! मेरे गुनाह पानी, बर्फ़ और ओलों से धो दे।", "तकबीर-ए-तहरीमा के बाद (सना की जगह भी पढ़ सकते हैं)।", "नबी ﷺ तकबीर और क़िराअत के दरमियान यह पढ़ते थे।"),
        "dua_hamdan_kathiran" to DuaText("रुकू के बाद बहुत ज़्यादा तारीफ़", "ऐ हमारे रब! तेरे ही लिए तारीफ़ है — बहुत ज़्यादा, पाकीज़ा और बरकत वाली तारीफ़।", "रुकू से उठकर 'रब्बना लकल-हम्द' के साथ।", "तीस से ज़्यादा फ़रिश्ते इसे पहले लिखने में एक-दूसरे से आगे बढ़ रहे थे।"),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन क़ुद्दूस (रुकू और सज्दा)", "(अल्लाह) बहुत पाक, निहायत मुक़द्दस है, फ़रिश्तों और रूह (जिब्रील) का रब।", "रुकू और सज्दे में।", "नबी ﷺ रुकू और सुजूद में यह पढ़ते थे।"),
        "dua_sujood_dhanbi_kullah" to DuaText("सज्दे में: मेरे सारे गुनाह माफ़ कर", "ऐ अल्लाह! मेरे सारे गुनाह माफ़ फ़रमा — छोटे और बड़े, पहले और बाद के, ज़ाहिर और छुपे।", "सज्दे में।", "सज्दा दुआ की क़बूलियत की जगह है।"),
        "dua_sujood_ridaka" to DuaText("तेरी रज़ा की पनाह", "ऐ अल्लाह! मैं तेरी रज़ा के ज़रिए तेरी नाराज़गी से, तेरी माफ़ी के ज़रिए तेरी सज़ा से पनाह माँगता हूँ, और तुझसे तेरी ही पनाह माँगता हूँ। मैं तेरी तारीफ़ का हक़ अदा नहीं कर सकता, तू वैसा ही है जैसी तूने अपनी तारीफ़ की।", "सज्दे में — हज़रत आइशा (रज़ि.) ने नबी ﷺ को यह पढ़ते सुना।", "नबी ﷺ की सज्दे की दुआ।"),
        "dua_tashahhud" to DuaText("तशह्हुद (अत्तहिय्यात)", "तमाम क़ौली, बदनी और माली इबादतें अल्लाह के लिए हैं। ऐ नबी! आप पर सलाम और अल्लाह की रहमत और बरकतें हों। हम पर और अल्लाह के नेक बंदों पर सलाम हो। मैं गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं, और गवाही देता हूँ कि मुहम्मद ﷺ उसके बंदे और रसूल हैं।", "हर क़ादे में — हज़रत अब्दुल्लाह बिन मसऊद (रज़ि.) की रिवायत (अहनाफ़ का मामूल)।", "नबी ﷺ इसे क़ुरआन की सूरत की तरह सिखाते थे।"),
        "dua_sajdah_tilawah" to DuaText("सज्दा-ए-तिलावत", "मेरे चेहरे ने उस ज़ात को सज्दा किया जिसने उसे पैदा किया और अपनी ताक़त और क़ुव्वत से उसके कान और आँखें बनाईं।", "सज्दा-ए-तिलावत में।", "नबी ﷺ रात के सज्दा-ए-तिलावत में यह पढ़ते थे।"),
        "dua_after_witr" to DuaText("वित्र के बाद", "पाक है बादशाह, निहायत मुक़द्दस।", "वित्र के सलाम के बाद तीन बार, तीसरी बार आवाज़ बुलंद करके।", "नबी ﷺ वित्र के बाद यह फ़रमाते।"),
        "dua_tahajjud_nur" to DuaText("तहज्जुद की शुरुआती दुआ", "ऐ अल्लाह! तेरे ही लिए तारीफ़ है, तू आसमानों, ज़मीन और जो उनमें है उनका क़ायम रखने वाला है। तेरे ही लिए तारीफ़ है, तू आसमानों, ज़मीन और जो उनमें है उनका नूर है। तेरे ही लिए तारीफ़ है, तू हक़ है, तेरा वादा हक़ है, तेरी मुलाक़ात हक़ है, तेरा क़ौल हक़ है, जन्नत हक़ है, जहन्नम हक़ है, अंबिया हक़ हैं, मुहम्मद ﷺ हक़ हैं और क़यामत हक़ है।", "रात की नमाज़ (तहज्जुद) शुरू करते वक़्त (दुआ का शुरुआती हिस्सा)।", "नबी ﷺ तहज्जुद के लिए उठकर यह पढ़ते थे (मुकम्मल दुआ बुख़ारी में है)।"),
        "dua_rabba_jibrail" to DuaText("इख़्तिलाफ़ी मामलों में रहनुमाई", "ऐ अल्लाह, जिब्रील, मीकाईल और इस्राफ़ील के रब, आसमानों और ज़मीन के पैदा करने वाले, छुपे और खुले के जानने वाले! तू अपने बंदों के दरमियान उन बातों का फ़ैसला करेगा जिनमें वे इख़्तिलाफ़ करते थे। जिस हक़ में इख़्तिलाफ़ किया गया, अपने हुक्म से उसमें मेरी रहनुमाई फ़रमा। बेशक तू जिसे चाहे सीधे रास्ते की हिदायत देता है।", "तहज्जुद की शुरुआत में — इख़्तिलाफ़ के वक़्त हक़ की हिदायत।", "नबी ﷺ रात की नमाज़ इसी दुआ से शुरू करते थे।"),
        "dua_going_to_mosque_nur" to DuaText("मस्जिद जाते वक़्त (नूर की दुआ)", "ऐ अल्लाह! मेरे दिल में नूर कर दे, मेरी आँखों में नूर, मेरे कानों में नूर, मेरे दाएँ नूर, मेरे बाएँ नूर, मेरे ऊपर नूर, मेरे नीचे नूर, मेरे आगे नूर, मेरे पीछे नूर, और मेरे लिए नूर बना दे।", "फ़ज्र के लिए मस्जिद जाते हुए।", "नबी ﷺ नमाज़ के लिए निकलते हुए यह पढ़ते थे।"),
        "dua_waswasa_salah" to DuaText("नमाज़ में वसवसा (ख़िंज़ब)", "मैं अल्लाह की पनाह माँगता हूँ मरदूद शैतान से।", "नमाज़ में शैतानी वसवसे आएँ तो पनाह माँगकर बाईं तरफ़ तीन बार हल्का थुत्कार।", "हज़रत उस्मान बिन अबिल-आस (रज़ि.) ने यह किया और वसवसा चला गया।"),
        "dua_alimal_ghayb" to DuaText("ग़ैब के जानने वाले", "ऐ अल्लाह, ग़ैब और हाज़िर के जानने वाले, आसमानों और ज़मीन के पैदा करने वाले, हर चीज़ के रब और मालिक! मैं गवाही देता हूँ कि तेरे सिवा कोई माबूद नहीं। मैं अपने नफ़्स के शर से, और शैतान के शर और उसके शिर्क से तेरी पनाह माँगता हूँ।", "सुबह, शाम और सोने से पहले — नबी ﷺ ने हज़रत अबू बक्र (रज़ि.) को सिखाई।", "नफ़्स और शैतान के शर से हिफ़ाज़त।"),
        "dua_fitratil_islam" to DuaText("इस्लाम की फ़ितरत पर", "हमने इस्लाम की फ़ितरत पर, कलिमा-ए-इख़लास पर, अपने नबी मुहम्मद ﷺ के दीन पर और अपने बाप इब्राहीम (अ.) की मिल्लत पर सुबह की, जो यकसू मुसलमान थे और मुशरिकों में से न थे।", "सुबह के वक़्त।", "हर सुबह ईमान की तजदीद।"),
        "dua_amsayna_fitrah" to DuaText("शाम को इस्लाम की फ़ितरत पर", "हमने इस्लाम की फ़ितरत पर, कलिमा-ए-इख़लास पर, अपने नबी मुहम्मद ﷺ के दीन पर और अपने बाप इब्राहीम (अ.) की मिल्लत पर शाम की, जो यकसू मुसलमान थे और मुशरिकों में से न थे।", "शाम के वक़्त।", "हर शाम ईमान की तजदीद।"),
        "dua_tahleel_10_fajr" to DuaText("फ़ज्र और मग़रिब के बाद दस बार तहलील", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाहत और तारीफ़ है, वही ज़िंदा करता और मारता है, और वह हर चीज़ पर क़ादिर है।", "फ़ज्र (और मग़रिब) के बाद, पाँव मोड़े और बात किए बिना दस बार।", "दस नेकियाँ, दस गुनाह माफ़, दस दर्जे बुलंद और दिन भर शैतान से हिफ़ाज़त।"),
        "dua_la_hawla_kanz" to DuaText("जन्नत का ख़ज़ाना", "अल्लाह के बिना न कोई ताक़त है और न कोई क़ुव्वत।", "हर वक़्त कसरत से।", "यह जन्नत के ख़ज़ानों में से एक ख़ज़ाना है।"),
        "dua_four_beloved_words" to DuaText("सबसे प्यारे चार कलिमे", "अल्लाह पाक है, सारी तारीफ़ अल्लाह के लिए है, अल्लाह के सिवा कोई माबूद नहीं, और अल्लाह सबसे बड़ा है।", "अल्लाह को सबसे पसंदीदा कलिमात।", "नबी ﷺ को यह हर उस चीज़ से ज़्यादा महबूब हैं जिस पर सूरज निकलता है।"),
        "dua_two_light_words" to DuaText("ज़बान पर हल्के दो कलिमे", "अल्लाह पाक है अपनी तारीफ़ के साथ, अल्लाह पाक है जो अज़मत वाला है।", "ज़बान पर हल्के, मीज़ान में भारी।", "रहमान को महबूब, ज़बान पर हल्के और मीज़ान में भारी। (बुख़ारी की आख़िरी हदीस)"),
        "dua_ya_dhal_jalal" to DuaText("या ज़ल-जलालि वल-इकराम", "ऐ जलाल और इकराम वाले!", "दुआ में इसे लाज़िम पकड़ो — नबी ﷺ का हुक्म।", "नबी ﷺ ने फ़रमाया: 'या ज़ल-जलालि वल-इकराम' को लाज़िम पकड़ो।"),
        "dua_sleep_wadatu_janbi" to DuaText("तेरे नाम से मैंने करवट रखी", "ऐ मेरे रब! तेरे नाम से मैंने अपना पहलू रखा और तेरे ही नाम से उठाऊँगा। अगर तू मेरी रूह रोक ले तो उस पर रहम फ़रमा, और अगर छोड़ दे तो उसकी ऐसे हिफ़ाज़त फ़रमा जैसे अपने नेक बंदों की हिफ़ाज़त करता है।", "बिस्तर झाड़कर लेटने के बाद।", "सोने से पहले रूह को अल्लाह के सुपुर्द करना।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("तूने मेरी जान पैदा की", "ऐ अल्लाह! तूने मेरी जान पैदा की और तू ही उसे वफ़ात देगा। उसका मरना और जीना तेरे ही लिए है। अगर तू उसे ज़िंदा रखे तो उसकी हिफ़ाज़त फ़रमा, और अगर मौत दे तो उसे बख़्श दे। ऐ अल्लाह! मैं तुझसे आफ़ियत माँगता हूँ।", "सोने से पहले — हज़रत इब्न उमर (रज़ि.) की रिवायत।", "नबी ﷺ ने सोने के वक़्त यह पढ़ने का हुक्म दिया।"),
        "dua_sleep_atamana" to DuaText("सोने से पहले शुक्र", "सारी तारीफ़ अल्लाह के लिए जिसने हमें खिलाया, पिलाया, हमारी ज़रूरत पूरी की और हमें ठिकाना दिया। कितने ही लोग हैं जिनका न कोई किफ़ायत करने वाला है न ठिकाना देने वाला।", "बिस्तर पर जाते वक़्त।", "नबी ﷺ बिस्तर पर जाते वक़्त यह फ़रमाते।"),
        "dua_sleep_rabbas_samawat" to DuaText("आसमानों के रब — हमारा क़र्ज़ अदा कर", "ऐ अल्लाह, आसमानों, ज़मीन और अर्श-ए-अज़ीम के रब, हमारे और हर चीज़ के रब, दाने और गुठली को फाड़ने वाले, तौरात, इंजील और फ़ुरक़ान उतारने वाले! मैं हर उस चीज़ के शर से तेरी पनाह माँगता हूँ जिसकी पेशानी तेरे क़ब्ज़े में है। ऐ अल्लाह! तू ही अव्वल है, तुझसे पहले कुछ नहीं; तू ही आख़िर है, तेरे बाद कुछ नहीं; तू ही ज़ाहिर है, तेरे ऊपर कुछ नहीं; तू ही बातिन है, तुझसे छुपा कुछ नहीं। हमारा क़र्ज़ अदा कर दे और हमें फ़क़्र से ग़नी कर दे।", "सोने से पहले दाईं करवट पर — हज़रत फ़ातिमा (रज़ि.) को सिखाई।", "क़र्ज़ और तंगदस्ती से नजात की दुआ।"),
        "dua_sleep_fear" to DuaText("नींद में डर या घबराहट", "मैं अल्लाह के मुकम्मल कलिमात की पनाह माँगता हूँ उसके ग़ज़ब और सज़ा से, उसके बंदों के शर से, और शैतानों के वसवसों से और इससे कि वे मेरे पास आएँ।", "नींद में घबराहट या डर लगे तो।", "ऐसा करने से वह चीज़ नुक़सान नहीं देगी।"),
        "dua_waking_afani" to DuaText("जागने पर: उसने मेरी रूह लौटा दी", "सारी तारीफ़ अल्लाह के लिए जिसने मेरे जिस्म को आफ़ियत दी, मेरी रूह मुझे लौटा दी और मुझे अपने ज़िक्र की इजाज़त दी।", "जागने पर।", "नई सुबह पर शुक्र।"),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाह मेरा रब है", "अल्लाह, अल्लाह मेरा रब है, मैं उसके साथ किसी चीज़ को शरीक नहीं करता।", "ग़म या परेशानी के वक़्त — नबी ﷺ ने हज़रत अस्मा बिन्त उमैस (रज़ि.) को सिखाई।", "परेशानी के वक़्त तौहीद का सहारा।"),
    )
}
